  "check_code": "import sqlite3\nfrom pathlib import Path\n\nTARGETS = {\n    \"PAY-20250324-00671\": {\"amount_cent\": 1248765327, \"version_before\": 4},\n    \"PAY-20250324-00672\": {\"amount_cent\": 631894786, \"version_before\": 4},\n}\nINCIDENT = \"INC-PAY-2025-0324-01\"\n\n\ndef _db(workspace):\n    workspace = Path(workspace)\n    return workspace.parent / \"system\" / \"treasury_payment_hub\" / \"state.db\"\n\n\ndef _connect(workspace):\n    connection = sqlite3.connect(_db(workspace))\n    connection.row_factory = sqlite3.Row\n    return connection\n\n\ndef check_incident_tag_and_version(workspace):\n    with _connect(workspace) as connection:\n        rows = connection.execute(\n            \"SELECT instruction_id, incident_id, version, status, amount_cent \"\n            \"FROM payment_instructions WHERE instruction_id IN (?, ?) ORDER BY instruction_id\",\n            tuple(TARGETS),\n        ).fetchall()\n    if len(rows) != 2:\n        return {\"score\": 0, \"detail\": \"目标指令记录不完整\"}\n    errors = []\n    for row in rows:\n        expected = TARGETS[row[\"instruction_id\"]]\n        if row[\"incident_id\"] != INCIDENT:\n            errors.append(f\"{row['instruction_id']} incident_id={row['incident_id']!r}\")\n        if row[\"version\"] != expected[\"version_before\"] + 1:\n            errors.append(f\"{row['instruction_id']} version={row['version']}\")\n        if row[\"status\"] != \"EXECUTED\":\n            errors.append(f\"{row['instruction_id']} status={row['status']!r}\")\n        if row[\"amount_cent\"] != expected[\"amount_cent\"]:\n            errors.append(f\"{row['instruction_id']} amount_cent={row['amount_cent']}\")\n    return {\"score\": 0 if errors else 1, \"detail\": \"; \".join(errors) if errors else \"两条指令事件标识、版本及核心支付事实正确\"}\n\n\ndef check_review_audit_records(workspace):\n    with _connect(workspace) as connection:\n        rows = connection.execute(\n            \"SELECT instruction_id, status_code, event_sequence, event_source, operator_id, remark \"\n            \"FROM instruction_status_log WHERE instruction_id IN (?, ?) \"\n            \"AND status_code='REVIEWED' AND event_source='OPERATIONS' AND operator_id='PERSON-incident-ops' \"\n            \"ORDER BY instruction_id, event_sequence\",\n            tuple(TARGETS),\n        ).fetchall()\n    errors = []\n    found = {key: [] for key in TARGETS}\n    for row in rows:\n        found[row[\"instruction_id\"]].append(row)\n    for instruction_id, entries in found.items():\n        if len(entries) != 1:\n            errors.append(f\"{instruction_id} 操作审计记录数={len(entries)}\")\n            continue\n        entry = entries[0]\n        if entry[\"event_sequence\"] != 5:\n            errors.append(f\"{instruction_id} event_sequence={entry['event_sequence']}\")\n        remark = entry[\"remark\"] or \"\"\n        if \"重复\" not in remark or \"事件\" not in remark:\n            errors.append(f\"{instruction_id} 审计原因未说明重复付款事件归属\")\n    return {\"score\": 0 if errors else 1, \"detail\": \"; \".join(errors) if errors else \"两条指令各有一条 REVIEWED 复盘审计记录\"}\n\n\ndef check_unchanged_payment_facts(workspace):\n    with _connect(workspace) as connection:\n        rows = connection.execute(\n            \"SELECT instruction_id, incident_id, version, status, amount_cent \"\n            \"FROM payment_instructions WHERE instruction_id IN (?, ?, ?) ORDER BY instruction_id\",\n            (\"PAY-20250324-00671\", \"PAY-20250324-00672\", \"PAY-20250324-00679\"),\n        ).fetchall()\n    by_id = {row[\"instruction_id\"]: row for row in rows}\n    errors = []\n    for instruction_id, expected in TARGETS.items():\n        row = by_id.get(instruction_id)\n        if not row or row[\"status\"] != \"EXECUTED\" or row[\"amount_cent\"] != expected[\"amount_cent\"]:\n            errors.append(f\"{instruction_id} 金额或执行状态被改变\")\n    unrelated = by_id.get(\"PAY-20250324-00679\")\n    if not unrelated or unrelated[\"incident_id\"] is not None or unrelated[\"version\"] != 3 or unrelated[\"status\"] != \"EXECUTED\" or unrelated[\"amount_cent\"] != 169339887:\n        errors.append(\"无关指令 PAY-20250324-00679 被改变\")\n    return {\"score\": 0 if errors else 1, \"detail\": \"; \".join(errors) if errors else \"目标金额/状态及无关指令均未被误改\"}\n",
